'use strict';
const main=document.querySelector('main'),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={fast_candidate:'신속 처리 후보',general_review:'일반 심사',detailed_review:'정밀 검토',unable_to_determine:'판단 불가',closed_auto:'자동 조사 종료',needs_review:'담당자 검토'};
let base=localStorage.getItem('aura-api')||(window.AURA_CONFIG?.apiBase||''),health=null,pid='',busy=false;
const fmt=n=>n==null?'—':Number(n).toLocaleString('ko-KR',{maximumFractionDigits:2}),json=v=>`<pre>${esc(JSON.stringify(v,null,2))}</pre>`,badge=v=>`<span class="badge ${['detailed_review','unable_to_determine'].includes(v)?'danger':''}">${esc(labels[v]||v)}</span>`;
const lead=(title,sub,actions='')=>`<div class="lead"><div><span class="eyebrow">INSURELENS / AURA 2.0</span><h1>${title}</h1><p class="muted">${sub}</p></div><div class="actions">${actions}</div></div>`;
const metric=(name,value,sub)=>`<div class="metric"><div class="label">${name}</div><div class="number">${value}</div><small>${sub}</small></div>`;
function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',5000);}
async function api(path,body){let r=await fetch(base+path,{headers:{'Content-Type':'application/json',...(sessionStorage.getItem('aura-token')?{'X-Aura-Token':sessionStorage.getItem('aura-token')}:{})},...(body!==undefined?{method:'POST',body:JSON.stringify(body)}:{})});if(!r.ok){let message;try{message=(await r.json()).detail;}catch{}throw Error(message||`API ${r.status}`);}return r.json();}
const table=rows=>rows.length?`<div class="table-wrap"><table><thead><tr><th>고객 ID</th><th>처리 경로</th><th>OVERALL</th><th>검토 사유</th><th>상태</th></tr></thead><tbody>${rows.map(r=>`<tr data-person="${esc(r.person_id)}" tabindex="0"><td><b>${esc(r.person_id)}</b></td><td>${badge(r.route)}</td><td>${fmt(r.scores.S_overall)}</td><td>${esc(r.reasons.join(', ')||'추가 예외 없음')}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">표시할 조사 결과가 없습니다.</div>';
function offline(){document.querySelector('#connection').textContent='백엔드 연결 필요';main.innerHTML=lead('AURA 연결 설정','FastAPI와 DB를 연결해 관제센터를 시작하세요.')+`<section class="panel"><h2>백엔드 주소</h2><p>GitHub Pages는 프론트엔드만 제공합니다. Python API는 별도로 실행하세요.</p><form id="connect"><input id="api-base" type="url" placeholder="http://127.0.0.1:8000" value="${esc(base)}" aria-label="API 주소"> <input id="admin-token" type="password" placeholder="관리자 토큰 (설정 시)" aria-label="관리자 토큰" autocomplete="off"> <button class="primary">연결</button></form><p><code>python -m uvicorn backend.api:app --host 127.0.0.1 --port 8000</code></p><a href="legacy.html">기존 브라우저 분석 열기 ↗</a></section>`;}
async function render(){if(busy)return;let page=location.hash.slice(1)||'control';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));try{health=await api('/api/health');document.querySelector('#connection').textContent=health.llm_configured?'● LLM 도구 조사 연결':'● 규칙 기반 조사 모드';if(page==='queue')await queue();else if(page==='workspace')await workspace();else if(page==='admin')await admin();else await control();}catch(e){offline();toast(e.message);}}
async function control(){let [c,rows]=await Promise.all([api('/api/control'),api('/api/investigations?queue=true')]);main.innerHTML=lead('AURA Control Center','필요한 사건에 집중하는 자동 조사 관제센터',`<a class="button" href="#admin">데이터 관리</a><button class="primary" data-action="run">전체 자동 조사 시작 ↗</button>`)+`<div class="banner"><strong>${health.dataset?'● 조사 준비 완료':'합성 데이터를 생성해 시작하세요'}</strong><p>${health.llm_configured?'도구 호출 → 근거 검증 → Safety Gate':'결정론적 조사 워크플로 · 실제 자율 Agent는 LLM 연결 후 실행됩니다.'}</p></div><div class="metrics">${metric('전체 조사 고객',fmt(c.total),'고객별 최신 조사')}${metric('자동 조사 종료',fmt(c.closed_auto),'추가 이상징후 조사 종료')}${metric('사람의 검토 필요',fmt(c.needs_review),'예외 처리함에서 확인')}${metric('자동화율',c.automation_rate==null?'—':fmt(c.automation_rate*100)+'%','자동 종료 / 전체 조사 고객')}</div><div class="grid"><section class="panel"><h2>긴급 예외 사건</h2>${table(rows.filter(r=>['detailed_review','unable_to_determine'].includes(r.route)).slice(0,6))}<p><a href="#queue">예외 처리함 전체 보기 →</a></p></section><section class="panel"><h2>시스템 실행 상태</h2>${[['진행 중 작업',c.running],['시스템 오류',c.errors],['안전 차단',c.safety_blocks],['평균 조사 시간',c.average_ms==null?'—':fmt(c.average_ms)+' ms']].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${v}</strong></div>`).join('')}<p class="muted">${esc(health.spec_note)}</p></section></div>`;}
async function queue(){main.innerHTML=lead('Review Queue','고위험·판단 불가·검증 실패 사건을 확인하세요.')+`<div class="filters"><select id="domain"><option value="all">전체 보험</option><option value="med">의료 신호 있음</option><option value="auto">자동차 신호 있음</option><option value="cross">교차 신호 있음</option></select><input id="reason" placeholder="검토 사유 검색"><button data-action="filter">필터 적용</button></div><section class="panel" id="queue-table"></section>`;await filter();}
async function filter(){let rows=await api('/api/investigations?queue=true&domain='+document.querySelector('#domain').value),reason=document.querySelector('#reason').value.toLowerCase();document.querySelector('#queue-table').innerHTML=table(rows.filter(r=>r.reasons.join(' ').toLowerCase().includes(reason)));}
async function workspace(){if(!pid){main.innerHTML=lead('Investigation Workspace','조사 결과를 확인할 고객을 선택하세요.')+`<section class="panel"><select id="person">${(await api('/api/people')).map(p=>`<option>${esc(p.id)}</option>`).join('')}</select> <button data-action="open">결과 열기</button></section>`;return;}let r=await api('/api/investigations/'+encodeURIComponent(pid));main.innerHTML=lead(pid+' · 조사 워크스페이스',r.mode==='tool_calling'?'AI 도구 조사 결과':'규칙 기반 조사 결과',`<button data-action="rerun">추가 조사</button><a class="button" href="#queue">목록으로</a>`)+`<div class="metrics">${['med','auto','cross','overall'].map((k,i)=>metric(['의료','자동차','교차','Overall'][i]+' 점수',fmt(r.scores['S_'+k]),'0–100 · 검토 우선순위')).join('')}</div><div class="grid"><section class="panel"><h2>조사 요약 ${badge(r.gate.route)}</h2>${r.report.claims.map(c=>`<p>${esc(c.text)}<br><small>evidence_ids: ${esc(c.evidence_ids.join(', '))}</small></p>`).join('')||'<p>조사가 완료되지 않았습니다.</p>'}<p>${esc(r.gate.reasons.join(', '))}</p></section><section class="panel"><h2>SQL · 결정론적 검증</h2>${badge(r.verification.passed?'검증 통과':'검증 실패')}${r.verification.checks.map(c=>`<div class="row"><span>${esc(c.check)}</span><strong>${c.passed?'✓':'실패'}</strong></div>`).join('')}</section></div><div class="grid">${['medical','auto'].map(k=>`<section class="panel"><h2>${k==='medical'?'의료보험':'자동차보험'} 이상징후</h2>${r[k].signals.map(s=>`<div class="row"><span>${esc(s.name)}</span><strong>${fmt(s.value)} / 기준 ${fmt(s.threshold)} ${s.hit?'●':''}</strong></div>`).join('')}<div class="score"><span style="width:${r[k].score}%"></span></div></section>`).join('')}</div><section class="panel"><h2>사고·진료 연결 및 지급 중복 대조</h2><p>D: ${fmt(r.duplicate.D)}원 · 비율: ${r.duplicate.duplicate_ratio==null?'—':fmt(r.duplicate.duplicate_ratio*100)+'%'}</p>${json(r.duplicate.matches)}<details><summary>연결 결과 · evidence_ids</summary>${json(r.links)}</details></section><div class="grid"><section class="panel"><h2>사건 타임라인</h2><div class="timeline">${r.timeline.sort((a,b)=>(a.service_date||a.accident_date).localeCompare(b.service_date||b.accident_date)).map(t=>`<p><strong>${esc(t.service_date||t.accident_date)}</strong> · ${esc(t.kind)}<br>${esc(t.id)} · 지급 ${fmt(t.paid_amount)}</p>`).join('')}</div></section><section class="panel"><h2>조사 실행 로그</h2>${json(r.logs)}<h2>담당자 검토 메모</h2><textarea id="review-note" aria-label="검토 메모"></textarea><p><button data-action="save-note">메모 저장</button></p></section></div>`;}
async function admin(){let [a,c,q]=await Promise.all([api('/api/admin'),api('/api/control'),api('/api/data/quality')]);main.innerHTML=lead('Administration','데이터 생성, 비교 평가, 조사 이력을 관리합니다.')+`<div class="grid"><section class="panel"><h2>합성 데이터 생성·재생성</h2><p class="muted">재생성하면 현재 청구와 조사 결과를 교체합니다. 감사 로그는 보존됩니다.</p><label>Seed <input id="seed" type="number" value="42"></label> <label>고객 <input id="people-count" type="number" value="500" min="10" max="5000"></label><p><button data-action="generate" class="primary">DB에 생성</button></p>${json(q)}</section><section class="panel"><h2>A / B / C 비교 실험</h2><p>동일 평가 고객 · C는 고객당 5회 실행. 실제 LLM 미연결 시 A/C는 미실행으로 남습니다.</p><button data-action="evaluate">평가 실행</button> <a class="button" href="${esc(base)}/api/evaluation/blind" target="_blank" rel="noopener">블라인드 평가 자료</a>${a.evaluation?Object.entries(a.evaluation.groups).map(([k,v])=>`<h3>${k} · ${esc(v.status)}</h3>${json(v.metrics||v.reason)}`).join(''):'<p class="muted">아직 실행한 평가가 없습니다.</p>'}</section></div><section class="panel"><h2>처리 경로 · 자동화 성능</h2>${json(c)}</section><section class="panel"><h2>모델 설정</h2><p>정책 변경은 담당자의 코드 검토·승인으로만 반영합니다.</p><details><summary>현재 설정</summary>${json(a.config)}</details></section><section class="panel"><h2>감사 로그 · 최근 100건</h2>${json(a.audit)}</section>`;}
async function action(name){if(busy)return;try{if(name==='filter')return await filter();if(name==='open'){pid=document.querySelector('#person').value;return await workspace();}if(name==='save-note'){await api('/api/review/'+pid,{note:document.querySelector('#review-note').value});return toast('검토 메모 저장 완료');}busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);toast('작업 실행 중입니다.');if(name==='generate')await api('/api/data/generate',{seed:Number(document.querySelector('#seed').value),people:Number(document.querySelector('#people-count').value)});if(name==='run'||name==='rerun')await api('/api/investigate',name==='rerun'?{person_id:pid}:{});if(name==='evaluate')await api('/api/evaluate',{});toast('작업을 완료했습니다.');}catch(e){toast(e.message);}finally{busy=false;if(!['filter','open','save-note'].includes(name))await render();}}
document.addEventListener('click',e=>{if(e.target.closest('#connection-settings')){offline();return;}let b=e.target.closest('[data-action]');if(b)action(b.dataset.action);let row=e.target.closest('[data-person]');if(row){pid=row.dataset.person;if(location.hash==='#workspace')workspace();else location.hash='workspace';}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-person]'))e.target.click();});
document.addEventListener('submit',e=>{if(e.target.id!=='connect')return;e.preventDefault();base=document.querySelector('#api-base').value.replace(/\/$/,'');localStorage.setItem('aura-api',base);sessionStorage.setItem('aura-token',document.querySelector('#admin-token').value);render();});
window.addEventListener('hashchange',render);render();
